import pandas as pd
import numpy as np
from typing import Dict

def run(inputs: Dict[str, pd.DataFrame]) -> Dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure target_state has the right columns and types
    if target_state.empty:
        target_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])
        target_state = target_state.astype({
            "order_id": "int64",
            "status": "object",
            "amount": "float64",
            "last_seq": "int64"
        })

    # Ensure cdc_events has the right columns and types
    if not cdc_events.empty:
        cdc_events["seq"] = cdc_events["seq"].astype("int64")
        cdc_events["order_id"] = cdc_events["order_id"].astype("int64")
        cdc_events["op"] = cdc_events["op"].astype("object")
        cdc_events["status"] = cdc_events["status"].astype("object")
        cdc_events["amount"] = cdc_events["amount"].astype("float64")

    # Step 1: Remove duplicate events (at-least-once delivery)
    # Keep distinct by seq
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Step 2: Build a dict of current state for fast lookup
    state_dict = {}
    if not target_state.empty:
        for _, row in target_state.iterrows():
            state_dict[row["order_id"]] = {
                "status": row["status"],
                "amount": row["amount"],
                "last_seq": row["last_seq"]
            }

    # Track which orders had rows (for tombstone detection)
    orders_with_rows = set(state_dict.keys())

    # Step 3: Process events in seq order per order
    # Group events by order_id and sort by seq
    if not cdc_events.empty:
        cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

        for _, event in cdc_events.iterrows():
            order_id = event["order_id"]
            seq = event["seq"]
            op = event["op"]
            status = event["status"]
            amount = event["amount"]

            # Replay guard: skip if order has row and seq <= last_seq
            if order_id in state_dict:
                if seq <= state_dict[order_id]["last_seq"]:
                    continue

            # Mark that this order has had a row (for tombstone tracking)
            orders_with_rows.add(order_id)

            if op in ("I", "U"):
                if order_id not in state_dict:
                    # Create new row
                    state_dict[order_id] = {
                        "status": status,
                        "amount": amount,
                        "last_seq": seq
                    }
                else:
                    # Update existing row
                    state_dict[order_id]["status"] = status
                    # For 'U', NULL amount leaves existing unchanged
                    if op == "U" and pd.isna(amount):
                        # Keep existing amount
                        pass
                    else:
                        # 'I' or 'U' with non-NULL: set amount
                        state_dict[order_id]["amount"] = amount
                    state_dict[order_id]["last_seq"] = seq
            elif op == "D":
                # Delete row
                if order_id in state_dict:
                    del state_dict[order_id]

    # Step 4: Build new_state
    new_state_rows = []
    for order_id, state in state_dict.items():
        new_state_rows.append({
            "order_id": order_id,
            "status": state["status"],
            "amount": state["amount"],
            "last_seq": state["last_seq"]
        })

    if new_state_rows:
        new_state = pd.DataFrame(new_state_rows)
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    new_state = new_state.astype({
        "order_id": "int64",
        "status": "object",
        "amount": "float64",
        "last_seq": "int64"
    })
    new_state = new_state.sort_values("order_id").reset_index(drop=True)

    # Step 5: Build tombstones
    # Tombstones: orders that had a row and whose LAST applied event is 'D'
    tombstone_rows = []

    if not cdc_events.empty:
        for order_id in orders_with_rows:
            # Find all events for this order, in seq order
            order_events = cdc_events[cdc_events["order_id"] == order_id].sort_values("seq")

            if not order_events.empty:
                # Apply replay guard and find the last applied event
                current_last_seq = -1
                if order_id in target_state["order_id"].values:
                    current_last_seq = target_state[target_state["order_id"] == order_id]["last_seq"].iloc[0]

                last_applied_event = None
                for _, event in order_events.iterrows():
                    if event["seq"] > current_last_seq:
                        last_applied_event = event

                # If the last applied event is a 'D', add to tombstones
                if last_applied_event is not None and last_applied_event["op"] == "D":
                    tombstone_rows.append({
                        "order_id": order_id,
                        "deleted_seq": last_applied_event["seq"]
                    })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])

    tombstones = tombstones.astype({
        "order_id": "int64",
        "deleted_seq": "int64"
    })
    tombstones = tombstones.sort_values("order_id").reset_index(drop=True)

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
